LDA _g7h_mask
EOR #$FF ; A = clear - bits mask
LDY _g7h_bL
AND ( _gfx_zp_ptr ),Y
ORA _g7h_fill
STA ( _gfx_zp_ptr ),Y
JMP _g7h_done
