LDA _g7h_fill
AND _gfx7_partLeft,X
STA _g7h_mask
LDA _gfx7_clrLeft,X
LDY _g7h_bL
AND ( _gfx_zp_ptr ),Y
ORA _g7h_mask
STA ( _gfx_zp_ptr ),Y
