STA ( _gfx_zp_ptr ),Y
INY
DEX
BNE _g7h_mid
_g7h_right :
; Right partial : byte at bR .
LDX _g7h_iR
LDA _g7h_fill
AND _gfx7_partRight,X
STA _g7h_mask
LDA _gfx7_clrRight,X
LDY _g7h_bR
AND ( _gfx_zp_ptr ),Y
ORA _g7h_mask
STA ( _gfx_zp_ptr ),Y
