INC _gfx_zp_ptr+1
_g7v_no_carry2 :
; 16 - bit countdown .
LDA _g7v_cntLo
BNE _g7v_dec
LDA _g7v_cntHi
BEQ _g7v_done
DEC _g7v_cntHi
_g7v_dec :
DEC _g7v_cntLo
LDA _g7v_cntLo
ORA _g7v_cntHi
BNE _g7v_loop
_g7v_done :
