; base the DL ' s first LMS uses ) .
LDA #$00
STA $58
LDA #$81
STA $59
; CHACTL default+character base .
LDA #$02
STA $D401 ; CHACTL
; Re - enable display : playfield normal width,normal
; DMA,no PMG,instructions fetched .
LDA #$22
STA $D400 ; DMACTL
CLI
